#!/usr/bin/env bash
#
# Render a Homebrew formula for a given version using the checksums file.
# Usage: render.sh <version> <checksums_file>
# Output: the rendered formula to stdout.
#
# Example:
#   ./render.sh 1.2.3 /path/to/cogito-checksums.txt
#
# The checksums file is generated by the release workflow:
#   sha256sum *.tar.gz *.zip > cogito-checksums.txt

set -euo pipefail

version="${1:?Usage: render.sh <version> <checksums_file>}"
checksums="${2:?Usage: render.sh <version> <checksums_file>}"

if [[ ! -f "$checksums" ]]; then
  echo "Error: checksums file not found: $checksums" >&2
  exit 1
fi

# Extract SHA-256 for each target from the checksums file.
sha_linux_x64=$(grep -E 'cogito-'"$version"'-x86_64-unknown-linux-gnu\.tar\.gz' "$checksums" | awk '{print $1}')
sha_linux_arm64=$(grep -E 'cogito-'"$version"'-aarch64-unknown-linux-gnu\.tar\.gz' "$checksums" | awk '{print $1}')
sha_macos_x64=$(grep -E 'cogito-'"$version"'-x86_64-apple-darwin\.tar\.gz' "$checksums" | awk '{print $1}')
sha_macos_arm64=$(grep -E 'cogito-'"$version"'-aarch64-apple-darwin\.tar\.gz' "$checksums" | awk '{print $1}')

# Verify all checksums were found.
for var in sha_linux_x64 sha_linux_arm64 sha_macos_x64 sha_macos_arm64; do
  if [[ -z "${!var}" ]]; then
    echo "Error: missing checksum for $var in $checksums" >&2
    exit 1
  fi
done

cat <<RUBY
# frozen_string_literal: true

class Cogito < Formula
  desc "Context harness for AI coding agents"
  homepage "https://github.com/Rene-Kuhm/cogito-harness"
  version "${version}"

  on_macos do
    on_arm do
      url "https://github.com/Rene-Kuhm/cogito-harness/releases/download/v${version}/cogito-${version}-aarch64-apple-darwin.tar.gz"
      sha256 "${sha_macos_arm64}"
    end

    on_intel do
      url "https://github.com/Rene-Kuhm/cogito-harness/releases/download/v${version}/cogito-${version}-x86_64-apple-darwin.tar.gz"
      sha256 "${sha_macos_x64}"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/Rene-Kuhm/cogito-harness/releases/download/v${version}/cogito-${version}-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "${sha_linux_arm64}"
    end

    on_intel do
      url "https://github.com/Rene-Kuhm/cogito-harness/releases/download/v${version}/cogito-${version}-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "${sha_linux_x64}"
    end
  end

  def install
    bin.install "cogito"
    pkgshare.install "README.md", "LICENSE"
  end

  test do
    system "#{bin}/cogito", "--version"
  end
end
RUBY
